function DETECTION_SCALAR(P, A):
    M <- P * A * P
    if P is the zero matrix: return 0
    pick (i, j) with P[i, j] != 0
    c <- M[i, j] / P[i, j]
    if M == c * P (within tolerance):
        return c            # A is detectable with scalar c
    else:
        return NONE         # A is not detectable

function TRANSVERSAL_COMPRESSION(P, terms[1..m], scalars[1..m]):
    s <- 0
    for i in 1..m:
        s <- s + scalars[i]        # additivity of detection values
    return s * P                   # = P * (sum_i terms[i]) * P
